Prova nuova da creare insieme alla rotta (non messa nel ramo: senza la rotta corretta sarebbe rossa). Contenuto esatto: import { describe, it, expect, vi, beforeEach } from 'vitest';

/**
 * LA ROTTA DEL LOTTO SUL CATALOGO, SENZA L'ELENCO DEI PRODOTTI.
 *
 * La pagina del lavoro massivo manda sempre i prodotti dell'anteprima (`productIds`), anche con
 * «Applica a tutti». Ma la rotta, se l'elenco mancava, applicava tutti i risultati del lavoro:
 * una chiamata a mano (o una pagina vecchia rimasta aperta) riscriveva anche i prodotti che il
 * negozio non aveva visto. Qui gira la rotta VERA con un database finto: senza elenco risponde
 * 400, non scrive niente e non prenota il lavoro, che resta «pronto».
 */

const db = vi.hoisted(() => ({
  prodotti: [] as Record<string, unknown>[],
  categorie: [{ id: 'pane', name: 'Pane', slug: 'pane', parent_id: null }] as Record<string, unknown>[],
  lavoro: null as Record<string, unknown> | null,
  lavoroApplicato: 0,
  scritture: [] as { id: unknown; valori: Record<string, unknown> }[],
}));

vi.mock('@/lib/funzioni-al-lancio', async (originale) => ({
  ...((await originale()) as Record<string, unknown>),
  AI_NEGOZI_ACCESA: true,
}));
vi.mock('@/lib/api/middleware', () => ({
  withSellerAuth:
    (h: (ctx: { user: { id: string }; req: Request }) => unknown) =>
    (req: Request) =>
      h({ user: { id: 'negozio-r03-lotto' }, req }),
}));
vi.mock('@/lib/logger', () => ({ logger: { error: vi.fn(), warn: vi.fn(), info: vi.fn(), spesa: vi.fn() } }));
vi.mock('@/lib/audit', () => ({ writeAudit: async () => undefined }));
vi.mock('@/lib/ai/moderation', () => ({ classifyProductPolicy: async () => ({ allowed: true }) }));
vi.mock('@/lib/supabase/server', async () => {
  const { fintoCatalogo } = await import('./aiuti/finto-catalogo');
  return fintoCatalogo(db);
});

import { POST } from '@/app/api/ai/catalog-batch/apply/route';

const prodotto = (id: string) => ({
  id, seller_id: 'negozio-r03-lotto', name: `Prodotto ${id}`, description: 'Una descrizione abbastanza lunga.',
  price: 5, compare_at_price: null, unit: 'pezzo', condition: 'nuovo', stock: 3, status: 'available',
  images: ['https://mycity.test/f.jpg'], tags: [], has_variants: false, category_id: 'pane', attributes: {},
});

async function applica(corpo: Record<string, unknown>) {
  const res = await POST(
    new Request('http://localhost/api/ai/catalog-batch/apply', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(corpo),
    }) as never,
  );
  return res.status;
}

beforeEach(() => {
  db.prodotti = [prodotto('p1'), prodotto('p2')];
  db.scritture = [];
  db.lavoroApplicato = 0;
  db.lavoro = {
    id: 'lavoro-1', seller_id: 'negozio-r03-lotto', operation: 'improve', status: 'ready',
    results: [
      { product_id: 'p1', patch: { name: 'Prodotto p1 migliorato' } },
      { product_id: 'p2', patch: { name: 'Prodotto p2 migliorato' } },
    ],
  };
});

describe('la rotta del lotto sul catalogo vuole l’elenco dei prodotti', () => {
  it('solo il lavoro, senza elenco: 400, nessuna scrittura sui prodotti, il lavoro resta «pronto»', async () => {
    const status = await applica({ jobId: 'lavoro-1' });
    expect(status, 'senza elenco la rotta applica ancora tutti i risultati').toBe(400);
    expect(db.scritture, 'senza elenco sono stati riscritti prodotti').toEqual([]);
    expect(db.lavoroApplicato, 'senza elenco il lavoro è stato prenotato').toBe(0);
    expect(db.lavoro?.status).toBe('ready');
  });

  it('elenco che non è una lista: 400 anche lui', async () => {
    expect(await applica({ jobId: 'lavoro-1', productIds: 'p1' })).toBe(400);
    expect(db.scritture).toEqual([]);
    expect(db.lavoroApplicato).toBe(0);
  });

  it('controprova: con l’elenco si applica solo quello che c’è dentro', async () => {
    expect(await applica({ jobId: 'lavoro-1', productIds: ['p1'] })).toBe(200);
    expect(db.scritture.map((s) => s.id)).toEqual(['p1']);
    expect(db.lavoroApplicato).toBeGreaterThan(0);
  });
});
